package com.example.starter.observation;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 创建分钟观测记录请求。
 *
 * @param requestId     全局唯一请求标识（幂等去重键）
 * @param operator      操作者标识（非空）
 * @param observationId 分钟观测记录唯一标识
 * @param stationId     站号
 * @param minuteUtc     观测时刻，ISO-8601 UTC 整分钟（如 2026-10-07T10:00:00Z）
 * @param reading       观测读数，十进制字符串，最多三位小数
 */
public record CreateMinuteObservationRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String operator,
        @NotBlank @Size(max = 64) String observationId,
        @NotBlank @Size(max = 64) String stationId,
        @NotBlank @Size(max = 64) String minuteUtc,
        @NotBlank @Pattern(regexp = "-?\\d+(\\.\\d{1,3})?", message = "reading must be a decimal string with at most 3 fraction digits")
        String reading) {
}

package com.example.starter.observation;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

/**
 * 分钟观测离线提交（三方合并）请求：携带基线版本与三个可编辑字段的完整候选值。
 *
 * @param requestId   全局唯一请求标识（幂等去重键）
 * @param operator    操作者标识（非空）
 * @param baseVersion 离线修改所基于的基线版本号
 * @param stationId   站号候选值
 * @param minuteUtc   观测时刻候选值，ISO-8601 UTC 整分钟
 * @param reading     观测读数候选值，十进制字符串，最多三位小数
 */
public record MergeMinuteObservationRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String operator,
        @NotNull @Min(1) Integer baseVersion,
        @NotBlank @Size(max = 64) String stationId,
        @NotBlank @Size(max = 64) String minuteUtc,
        @NotBlank @Pattern(regexp = "-?\\d+(\\.\\d{1,3})?", message = "reading must be a decimal string with at most 3 fraction digits")
        String reading) {
}

package com.example.starter.observation;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 删除分钟观测记录请求：仅当 expectedVersion 匹配当前版本时生成新版本墓碑。
 *
 * @param requestId       全局唯一请求标识（幂等去重键）
 * @param operator        操作者标识（非空）
 * @param expectedVersion 期望删除时的当前版本号
 */
public record DeleteMinuteObservationRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String operator,
        @NotNull @Min(1) Integer expectedVersion) {
}

package com.example.starter.observation;

import com.fasterxml.jackson.annotation.JsonInclude;

import java.time.Instant;

/**
 * 分钟观测记录响应：普通版本携带全部业务字段；删除墓碑版本只返回删除状态和版本，不带业务字段。
 *
 * @param observationId 分钟观测记录唯一标识
 * @param version       版本号
 * @param deleted       是否为删除墓碑
 * @param stationId     站号（墓碑版本不返回）
 * @param minuteUtc     观测时刻（UTC 整分钟，ISO-8601；墓碑版本不返回）
 * @param reading       观测读数（墓碑版本不返回）
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record MinuteObservationResponse(
        String observationId,
        int version,
        boolean deleted,
        String stationId,
        Instant minuteUtc,
        String reading) {

    /**
     * 由快照构造响应；墓碑版本自动省略业务字段。
     */
    public static MinuteObservationResponse of(MinuteObservationSnapshot snapshot) {
        if (snapshot.deleted()) {
            return new MinuteObservationResponse(snapshot.observationId(), snapshot.version(), true,
                    null, null, null);
        }
        return new MinuteObservationResponse(snapshot.observationId(), snapshot.version(), false,
                snapshot.stationId(), snapshot.minuteUtc(), snapshot.reading());
    }
}

