private List<ExcursionInterval> computeIntervals(List<AnalysisReference> sortedRefs, BigDecimal threshold, int n) {
    List<ExcursionInterval> intervals = new ArrayList<>();
    Instant runStart = null;
    Instant previousMinute = null;
    int runLength = 0;
    for (AnalysisReference ref : sortedRefs) {
        boolean exceed = ValueParsers.parseDecimal(ref.reading(), "reading").compareTo(threshold) > 0;
        if (exceed) {
            if (runLength > 0 && ref.minuteUtc().equals(previousMinute.plusSeconds(60))) {
                runLength++;
            } else {
                if (runLength >= n) intervals.add(new ExcursionInterval(runStart, previousMinute.plusSeconds(60)));
                runStart = ref.minuteUtc();
                runLength = 1;
            }
        } else {
            if (runLength >= n) intervals.add(new ExcursionInterval(runStart, previousMinute.plusSeconds(60)));
            runLength = 0;
            runStart = null;
        }
        previousMinute = ref.minuteUtc();
    }
    if (runLength >= n) intervals.add(new ExcursionInterval(runStart, previousMinute.plusSeconds(60)));
    return intervals;
}
