    deleteBody.put("expectedVersion", 1);
    mockMvc.perform(post("/api/minute-observations/mo-2/delete")
                    .contentType(MediaType.APPLICATION_JSON)
                    .content(objectMapper.writeValueAsString(deleteBody)))
            .andExpect(status().isOk());

