    }

    @Test
    void failedAnalysisDoesNotOccupyRequestId() throws Exception {
        createObs("req-k1", "mo-1", "ST-A", "2026-10-07T10:00:00Z", "11");
        createObs("req-k2", "mo-2", "ST-A", "2026-10-07T10:01:00Z", "11");
