void tombstoneReferenceReturns422AndStaleVersionReturns409() throws Exception {
    createObs("req-t1", "mo-1", "ST-A", "2026-10-07T10:00:00Z", "11");
    createObs("req-t2", "mo-2", "ST-A", "2026-10-07T10:01:00Z", "11");
